 if(error||callback.fragment.length||!path||duplicate||![values[@"state"] isEqual:state]||![values[@"code"] length]||epoch!=[s.epochs[identifier] unsignedIntegerValue]){completion(nil,AuthError(DXLoc(@"登录已取消或授权回调校验失败，原连接保持不变。")));return;}
