- (void)credential:(NSDictionary *)c completion:(void(^)(NSString *,NSError *))completion{
 if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{[self credential:c completion:completion];});return;}
 NSString *identifier=c[@"id"]?:@"";NSDictionary *oauth=TFAIProvider(c[@"protocol"])[@"oauth"],*record=ReadToken(identifier);NSURL *url=[NSURL URLWithString:c[@"baseURL"]],*official=[NSURL URLWithString:TFAIProvider(c[@"protocol"])[@"baseURL"]];if(!oauth||!OfficialBase(url,official)){completion(nil,AuthError(DXLoc(@"OAuth 连接地址已变化，请恢复官方地址并重新登录。")));return;}
 if(![record[@"accessToken"] length]){completion(nil,AuthError(DXLoc(@"请先登录此连接。")));return;}
 if(![record[@"kind"] isEqual:oauth[@"kind"]]||([oauth[@"kind"] isEqual:@"google"]&&![record[@"clientID"] isEqual:c[@"oauthClientID"]])){completion(nil,AuthError(DXLoc(@"服务商或OAuth客户端已变化，请退出旧授权后重新登录。")));return;}
