}
- (void)logout:(NSDictionary *)c completion:(TFAIResult)completion{
 if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{[self logout:c completion:completion];});return;}
 NSString *identifier=c[@"id"]?:@"";self.epochs[identifier]=@([self.epochs[identifier] unsignedIntegerValue]+1);NSArray *waiting=[self.waiters[identifier] copy];[self.waiters removeObjectForKey:identifier];for(void(^cb)(NSString *,NSError *) in waiting)cb(nil,AuthError(DXLoc(@"已退出登录。")));self.loginSerial++;[self.web cancel];self.web=nil;NSDictionary *record=ReadToken(identifier),*oauth=TFAIProvider(c[@"protocol"])[@"oauth"];OSStatus deleted=SecItemDelete((__bridge CFDictionaryRef)TokenQuery(identifier));if(deleted!=errSecSuccess&&deleted!=errSecItemNotFound){completion(nil,AuthError(DXLoc(@"钥匙串清除失败，请重试退出。")));return;}
